// C1 Leser, Schritt 1: Maklerpost filtern.
// Betreff und Absender stehen bei n8n-nodes-imap unter envelope, nicht direkt im Item.
// Suchauftragsmails von myscout@immobilienscout24.de holt S1 und werden hier verworfen.
const ohneTags = h => String(h || '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/p>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/[ \t]+/g, ' ');

const raus = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const e = j.envelope || {};
  const betreff = String(e.subject || j.subject || '');
  const absender = []
    .concat(e.from || [])
    .map(a => String((a && a.address) || '')).join(', ') || String(j.from || '');
  if (absender.toLowerCase().includes('myscout@immobilienscout24.de')) continue;
  const text = String(j.textContent || '').trim() || ohneTags(j.htmlContent);
  const suchraum = betreff + '\n' + text;
  const treffer = [...suchraum.matchAll(/\b(\d{8,12})\b/g)].map(m => m[1]);
  const info = Array.isArray(j.attachmentsInfo) ? j.attachmentsInfo : [];
  const anhaenge = info.filter(a => /pdf/i.test(String(a.contentType || a.filename || '')));
  raus.push({ json: {
    uid: j.uid,
    betreff: betreff,
    absender: absender,
    empfangen_am: e.date || j.date || null,
    mailtext: text,
    kandidaten: [...new Set(treffer)],
    hat_pdf: anhaenge.length > 0,
  }});
}
return raus;

// S2 Schwaerzer (E38): Hausnummer und Kontaktdaten raus, Strasse und Stadtteil bleiben.
// Eingabe: die gefilterten Mails, bei PDF zusaetzlich der ausgelesene Text.
// Ausgabe: ein Item je Mail mit geschwaerztem Text. Fail-closed: ohne Text kein Modellaufruf.
// Die Anhangstexte kommen ohne UID zurueck. Sie stehen aber in derselben Reihenfolge
// wie die Mails mit Anhang. Stimmt die Zahl nicht, wird kein Anhang zugeordnet (fail-closed).
// Der Knoten "Extract From PDF" legt den Text unter text ab.
const pdfTexte = $input.all().map(i => String(((i.json || {}).pdf_text) || ((i.json || {}).text) || '')).filter(Boolean);
const mails = $('Maklerpost filtern').all();
const mitPdf = mails.filter(i => (i.json || {}).hat_pdf).length;
const passt = pdfTexte.length === mitPdf;
let k = 0;

function schwaerzen(t) {
  let s = String(t || '');
  s = s.replace(/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g, '[Kontakt entfernt]');
  s = s.replace(/https?:\/\/\S+/g, '[Verweis entfernt]');
  s = s.replace(/\bwww\.\S+/gi, '[Verweis entfernt]');
  // Rufnummern: +49..., 0221/..., 0170 ...
  s = s.replace(/(?<![\d])(?:\+\d{1,3}[\s\/-]?)?\(?0\d{2,5}\)?[\s\/-]?\d{3,}(?:[\s\/-]?\d+)*/g, m =>
    (m.replace(/\D/g, '').length >= 7 ? '[Rufnummer entfernt]' : m));
  // Hausnummer nach einem Strassennamen: Wort auf -strasse/-str./-weg/-platz/-allee/-gasse/-ring/-damm
  s = s.replace(/([A-ZÄÖÜ][\wÄÖÜäöüß.-]*(?:stra(?:ß|ss)e|str\.|weg|platz|allee|gasse|ring|damm|ufer|chaussee))\s+\d+\s*[a-zA-Z]?\b/g,
    '$1 [Hausnummer entfernt]');
  return s.replace(/[ \t]{2,}/g, ' ').trim();
}

const raus = [];
for (const i of mails) {
  const j = i.json || {};
  const pdf = (j.hat_pdf && passt) ? (pdfTexte[k++] || '') : '';
  const teile = [j.mailtext, pdf].filter(Boolean);
  const roh = teile.join('\n\n--- Anhang ---\n\n');
  const text = schwaerzen(roh);
  const gekuerzt = text.slice(0, 60000);
  const anweisung = [
    'Du liest den Text eines Immobilien-Exposes und fuellst nur erlaubte Felder.',
    'Erlaubt sind ausschliesslich: zimmer, etage, baujahr, stadtteil, ausstattung.',
    'Verboten sind Preis, Wohnflaeche, Hausgeld, Ruecklage und Energiekennwert. Nenne sie nie.',
    'Fuelle ein Feld nur, wenn der Text es klar sagt. Sonst null.',
    'Gib zu jedem gefuellten Feld genau ein Zitat aus dem Text.',
    'Das Zitat muss eine zusammenhaengende Stelle sein, Zeichen fuer Zeichen abgeschrieben.',
    'Setze nie zwei Stellen zusammen, kuerze nicht mit Auslassungspunkten, formuliere nicht um.',
    'Findest du keine einzelne Stelle, die den Wert traegt, setze das Feld auf null.',
    'Antworte nur mit JSON in dieser Form:',
    '{"zimmer": Zahl oder null, "etage": Text oder null, "baujahr": Zahl oder null,',
    ' "stadtteil": Text oder null, "ausstattung": [Text], "belege": {"feld": "Zitat"}}',
  ].join('\n');
  raus.push({ json: {
    uid: j.uid,
    betreff: schwaerzen(j.betreff),
    empfangen_am: j.empfangen_am,
    kandidaten: j.kandidaten || [],
    expose_id: (j.kandidaten || [])[0] || '',
    zeichen: gekuerzt.length,
    lesbar: gekuerzt.length >= 200 && !!((j.kandidaten || [])[0]),   // ohne Exposenummer kein Modellaufruf
    text: gekuerzt,
    body: {
      model: 'gpt-oss-120b',
      temperature: 0,
      max_tokens: 3000,
      reasoning_effort: 'low',   // gpt-oss denkt sonst das Fenster leer
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: anweisung },
        { role: 'user', content: gekuerzt },
      ],
    },
  }});
}
return raus;

// C1 Leser, Schritt 3: Antwort des lokalen Modells pruefen.
// Positivliste nach Konzept 5.7: nur zimmer, etage, baujahr, stadtteil, ausstattung.
// Preis, Wohnflaeche, Hausgeld, Ruecklage und Energiekennwert bleiben gesperrt (R6).
// Gefuellte Felder tragen die Marke "modell" und zaehlen nicht in die Belegdichte (R8).
const ERLAUBT = ['zimmer', 'etage', 'baujahr', 'stadtteil', 'ausstattung'];

// Zitatanker (R1, R7): ein Beleg zaehlt nur, wenn er woertlich im geschwaerzten Text steht.
// Verglichen wird ohne Mehrfachleerzeichen und ohne Gross- und Kleinschreibung.
const norm = t => String(t || '').replace(/\s+/g, ' ').toLowerCase();
const belegtIm = (zitat, text) => {
  const z = norm(zitat);
  return z.length >= 8 && norm(text).includes(z);
};

const quelle = $('S2 Schwaerzer').all();
const raus = [];
const antworten = $input.all();

for (let i = 0; i < antworten.length; i++) {
  const a = (antworten[i] || {}).json || {};
  const q = ((quelle[i] || {}).json) || {};
  let felder = {}, grund = '';
  const ungeprueft = [];

  const inhalt = a.choices && a.choices[0] && a.choices[0].message
    ? (a.choices[0].message.content || '') : '';
  if (!inhalt) grund = 'keine Antwort vom Modell';

  if (inhalt) {
    const start = inhalt.indexOf('{'), ende = inhalt.lastIndexOf('}');
    try {
      const roh = JSON.parse(start >= 0 ? inhalt.slice(start, ende + 1) : inhalt);
      const belege = (roh && typeof roh.belege === 'object' && roh.belege) || {};
      for (const k of ERLAUBT) {
        let w = roh ? roh[k] : null;
        if (w === undefined || w === null || w === '') continue;
        if (k === 'ausstattung') {
          w = Array.isArray(w) ? w.map(x => String(x)).filter(Boolean).slice(0, 12) : [String(w)];
          if (!w.length) continue;
        }
        if (k === 'zimmer' || k === 'baujahr') {
          const z = Number(String(w).replace(',', '.'));
          if (!isFinite(z)) continue;
          w = z;
        }
        const zitat = String(belege[k] || '').slice(0, 300);
        const geprueft = belegtIm(zitat, q.text);
        if (!geprueft) ungeprueft.push(k);      // Wert bleibt, der Beleg gilt als nicht belegt (R1, R7)
        felder[k] = { wert: w, marke: 'modell', beleg: zitat, beleg_geprueft: geprueft };
      }
    } catch (e) { grund = 'Antwort war kein JSON'; }
  }

  const anzahl = Object.keys(felder).length;
  raus.push({ json: {
    uid: q.uid,
    expose_id: String(q.expose_id || ''),
    objekt_schluessel: q.expose_id ? ('is24:' + q.expose_id) : '',
    expose_status: anzahl ? 'gelesen' : 'ohne_felder',
    expose_grund: grund || (ungeprueft.length ? ('Beleg nicht woertlich: ' + ungeprueft.join(', ')) : ''),
    ungepruefte_felder: ungeprueft,
    expose_am: new Date().toISOString(),
    expose_felder: JSON.stringify(felder),
    anzahl_felder: anzahl,
    betreff: q.betreff || '',
  }});
}
return raus;

// UIDs der verarbeiteten Mails einsammeln. Ohne UID endet der Zweig hier.
const liste = $('Antwort pruefen').all()
  .map(i => (i.json || {}).uid)
  .filter(u => u !== undefined && u !== null);
if (!liste.length) return [];
return [{ json: { uid_list: liste.join(',') } }];

// UIDs der unlesbaren Mails einsammeln. Ohne UID endet der Zweig hier.
const liste = $('S2 Schwaerzer').all()
  .filter(i => !(i.json || {}).lesbar)
  .map(i => (i.json || {}).uid)
  .filter(u => u !== undefined && u !== null);
if (!liste.length) return [];
return [{ json: { uid_list: liste.join(',') } }];
